def evaluate(current_reputation, observation, my_history, round_num):
    # Use a faster update rate and scale the delta more aggressively
    if observation['action'] == 'cooperate':
        delta = 1.0
    else:
        delta = -1.0

    # Give recent action more weight (50/50 split)
    new_rep = 0.5 * current_reputation + 0.5 * delta

    # Add a small round-based adjustment: be more cautious early on
    if round_num < 5:
        # In early rounds, pull reputation slightly toward neutral
        new_rep = 0.9 * new_rep + 0.1 * 0.0

    # Clamp to valid range
    return max(-1.0, min(1.0, new_rep))


def decide(recipient_reputation, round_num, my_history):
    import random

    # Use a stricter threshold for unconditional cooperation
    if recipient_reputation > 0.5:
        return True

    # For lower reputation, choose probabilistically based on reputation value
    # Map reputation from [-1, 0.5] to cooperation probability in [0.0, 0.8]
    if recipient_reputation <= -1.0:
        prob_coop = 0.0
    else:
        # Linear interpolation: at rep=-1 => 0.0, at rep=0.5 => 0.8
        prob_coop = (recipient_reputation + 1.0) / 1.5 * 0.8

    # Adjust probability based on own past behavior
    # If we have been cooperating a lot, we are slightly more trusting of low reputations
    if my_history:
        coop_count = sum(1 for a in my_history if a)
        total = len(my_history)
        if total > 0:
            coop_ratio = coop_count / total
            # Increase probability if we have cooperated more than 60% of the time
            if coop_ratio > 0.6:
                prob_coop = min(0.9, prob_coop + 0.15)
            # Decrease probability if we have defected more than 60% of the time
            elif coop_ratio < 0.4:
                prob_coop = max(0.0, prob_coop - 0.15)

    return random.random() < prob_coop
